"use client"

import * as React from "react"
import { Input as InputPrimitive } from "@base-ui/react/input"
import { cva, type VariantProps } from "class-variance-authority"
import { cn } from "@/lib/utils"
import { Tooltip, TooltipContent } from "./tooltip"

const inputVariants = cva(
  "w-full min-w-0 rounded-md border border-input bg-card text-sm transition-colors duration-fast ease-entrance outline-none file:inline-flex file:h-6 file:border-0 file:bg-transparent file:text-sm file:font-medium file:text-foreground placeholder:text-muted-foreground focus-visible:border-ring disabled:pointer-events-none disabled:cursor-not-allowed disabled:bg-muted/50 disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-0 aria-invalid:focus-visible:ring-1 aria-invalid:focus-visible:ring-destructive dark:disabled:bg-muted/80 dark:aria-invalid:border-destructive/50 dark:aria-invalid:ring-destructive/40",
  {
    variants: {
      size: {
        // Field heights are density tokens (styles.css): compact 32/36/40 — the
        // Button sm/md/lg — and data-density="comfortable" 36/44/52.
        sm: "h-(--field-sm) px-3 text-[13px]",
        default: "h-(--field-md) px-3",
        lg: "h-(--field-lg) px-3",
      },
    },
    defaultVariants: {
      size: "default",
    },
  }
)

/**
 * Text input. Constraint validation (`required`, `type="email"`, `pattern`,
 * `minLength`…) answers in the WunderUI tooltip instead of the browser's own
 * bubble: on submit the first invalid field is focused and shows the browser's
 * message in a Tooltip, and the message clears as soon as the user types or
 * leaves the field.
 */
function Input({
  className,
  type,
  size = "default",
  ref,
  onInvalid,
  onInput,
  onBlur,
  ...props
}: Omit<React.ComponentProps<"input">, "size"> & VariantProps<typeof inputVariants>) {
  const inputRef = React.useRef<HTMLInputElement | null>(null)
  const [message, setMessage] = React.useState<string | null>(null)
  const shown = React.useRef("")
  if (message) shown.current = message

  const setRefs = React.useCallback(
    (node: HTMLInputElement | null) => {
      inputRef.current = node
      if (typeof ref === "function") ref(node)
      else if (ref) (ref as React.RefObject<HTMLInputElement | null>).current = node
    },
    [ref]
  )

  return (
    <>
      <InputPrimitive
        ref={setRefs}
        type={type}
        data-slot="input"
        className={cn(inputVariants({ size }), className)}
        onInvalid={(event: React.FormEvent<HTMLInputElement>) => {
          onInvalid?.(event)
          if (event.defaultPrevented) return
          event.preventDefault()
          const input = event.currentTarget
          // Every invalid field fires; only the first one in the form speaks.
          // Controls only: a <fieldset> around an invalid field matches :invalid too
          // and comes first in document order, which would silence every field in it.
          const first = input.form?.querySelector<HTMLElement>(":is(input, select, textarea):invalid")
          if (first && first !== input) return
          input.focus()
          setMessage(input.validationMessage)
        }}
        onInput={(event: React.InputEvent<HTMLInputElement>) => {
          onInput?.(event)
          if (message) setMessage(null)
        }}
        onBlur={(event: React.FocusEvent<HTMLInputElement>) => {
          onBlur?.(event)
          if (message) setMessage(null)
        }}
        {...props}
        aria-invalid={message ? true : props["aria-invalid"]}
      />
      <Tooltip open={!!message}>
        <TooltipContent anchor={inputRef} side="bottom" align="start" role="alert">
          {shown.current}
        </TooltipContent>
      </Tooltip>
    </>
  )
}

export { Input, inputVariants }

"use client"

import * as React from "react"
import { Tooltip as TooltipPrimitive } from "@base-ui/react/tooltip"
import { cn } from "@/lib/utils"

function Tooltip({ ...props }: TooltipPrimitive.Root.Props) {
  return <TooltipPrimitive.Root data-slot="tooltip" {...props} />
}

function TooltipTrigger({ ...props }: TooltipPrimitive.Trigger.Props) {
  return <TooltipPrimitive.Trigger data-slot="tooltip-trigger" {...props} />
}

function TooltipContent({
  className,
  sideOffset = 8,
  children,
  side = "top",
  align,
  anchor,
  shortcut,
  linger = false,
  ...props
}: TooltipPrimitive.Popup.Props &
  Pick<TooltipPrimitive.Positioner.Props, "sideOffset" | "side" | "align" | "anchor"> & {
    /** Keyboard hint rendered after the label, e.g. "⌘K" (Figma Type=shortcut). */
    shortcut?: string
    /**
     * For confirmations such as "Copied to clipboard": appears at once and,
     * when closed, drifts up slightly while it fades out slowly instead of
     * snapping away.
     */
    linger?: boolean
  }) {
  return (
    <TooltipPrimitive.Portal>
      <TooltipPrimitive.Positioner className="isolate z-50 outline-none" sideOffset={sideOffset} side={side} align={align} anchor={anchor}>
        <TooltipPrimitive.Popup
          data-slot="tooltip-content"
          className={cn(
            // fill-mode-both: the popup is invisible during the enter delay and stays
            // invisible after the exit — without it, it flashes at full opacity at both ends.
            "z-50 inline-flex items-center rounded-[6px] bg-neutral-dark-content px-4 py-2 text-xs font-medium text-neutral-white shadow-md fill-mode-both data-open:animate-in data-open:data-instant:animate-none data-closed:data-instant:animate-none data-open:fade-in-0 origin-(--transform-origin) data-open:zoom-in-98 data-open:duration-fast data-open:delay-instant data-open:ease-entrance data-closed:animate-out data-closed:fade-out-0 data-closed:zoom-out-98 data-closed:duration-instant data-closed:ease-exit",
            linger &&
              "data-open:delay-0 data-open:slide-in-from-bottom-1 data-closed:zoom-out-100 data-closed:slide-out-to-top-1 data-closed:duration-ambient data-closed:ease-move",
            className
          )}
          {...props}
        >
          {children}
          {shortcut && (
            <kbd className="ml-2 inline-flex h-4 items-center rounded-[3px] bg-white/15 px-1 font-sans text-[10px] font-medium text-white/90">
              {shortcut}
            </kbd>
          )}
          {/* The arrow points down by default (tooltip above the trigger); when the
              tooltip flips or sits beside the trigger it turns to keep pointing at it. */}
          <TooltipPrimitive.Arrow className="data-[side=bottom]:top-[-4px] data-[side=bottom]:rotate-180 data-[side=left]:right-[-6px] data-[side=left]:-rotate-90 data-[side=right]:left-[-6px] data-[side=right]:rotate-90 data-[side=top]:bottom-[-4px]">
            <svg width="10" height="5" viewBox="0 0 10 5" fill="none">
              <path d="M0 0L5 5L10 0Z" className="fill-neutral-dark-content" />
            </svg>
          </TooltipPrimitive.Arrow>
        </TooltipPrimitive.Popup>
      </TooltipPrimitive.Positioner>
    </TooltipPrimitive.Portal>
  )
}

export { Tooltip, TooltipTrigger, TooltipContent }

import type { CnFunction } from "cn"
import { createCn } from "cn/config"

/**
 * clsx + tailwind-merge, taught WunderUI's own theme utilities so they merge
 * in the right group: `text-label-sm` is a font size (not a text colour, which
 * dropped it next to `text-text-tertiary`), `bg-gradient-*` a background image
 * (not a colour that `bg-card` would remove), and the motion utilities
 * `ease-entrance …` and `duration-fast …` replace each other.
 */
export const cn: CnFunction = createCn({
  extend: {
    classGroups: {
      "font-size": [{ text: ["label-sm"] }],
      "bg-image": [
        {
          bg: [
            "gradient-primary",
            "gradient-indigo",
            "gradient-blue",
            "gradient-purple",
            "gradient-pink",
            "gradient-red",
            "gradient-orange",
            "gradient-yellow",
            "gradient-green",
            "gradient-alternative",
            "gradient-slate",
            "gradient-dark",
          ],
        },
      ],
      ease: [{ ease: ["entrance", "exit", "move", "overshoot", "spring"] }],
      duration: [{ duration: ["instant", "fast", "base", "slow", "deliberate", "ambient"] }],
    },
  },
})
